//! Declarative command/argument specification, modelled on clap v4 semantics.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ValueKind {
    /// Flag; takes no value.
    None,
    /// Takes exactly one value.
    Required,
    /// Value is optional (`--opt` or `--opt=v`).
    Optional,
}

#[derive(Clone)]
pub struct Arg {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub hidden_long_aliases: Vec<&'static str>,
    pub hidden_short_aliases: Vec<char>,
    pub value_name: Option<&'static str>,
    pub value: ValueKind,
    /// Positional argument
    pub positional: bool,
    /// May be supplied more than once / accepts many values
    pub multiple: bool,
    pub required: bool,
    pub help: &'static str,
    pub long_help: Option<&'static str>,
    pub heading: Option<&'static str>,
    pub hide: bool,
    pub conflicts: Vec<&'static str>,
    pub requires: Vec<&'static str>,
    pub overrides: Vec<&'static str>,
    pub possible: Vec<&'static str>,
    pub default: Option<&'static str>,
    pub allow_hyphen: bool,
    /// Consume everything after this positional verbatim
    pub trailing: bool,
    /// Number of values consumed for a `Required` value option (>1 => multi-value)
    pub num_values: usize,
}

impl Arg {
    pub fn new(id: &'static str) -> Arg {
        Arg {
            id,
            short: None,
            long: None,
            hidden_long_aliases: Vec::new(),
            hidden_short_aliases: Vec::new(),
            value_name: None,
            value: ValueKind::None,
            positional: false,
            multiple: false,
            required: false,
            help: "",
            long_help: None,
            heading: None,
            hide: false,
            conflicts: Vec::new(),
            requires: Vec::new(),
            overrides: Vec::new(),
            possible: Vec::new(),
            default: None,
            allow_hyphen: false,
            trailing: false,
            num_values: 1,
        }
    }

    pub fn positional(id: &'static str) -> Arg {
        let mut a = Arg::new(id);
        a.positional = true;
        a.value = ValueKind::Required;
        a.value_name = Some(id);
        a
    }

    pub fn short(mut self, c: char) -> Self {
        self.short = Some(c);
        self
    }
    pub fn long(mut self, l: &'static str) -> Self {
        self.long = Some(l);
        self
    }
    pub fn alias(mut self, l: &'static str) -> Self {
        self.hidden_long_aliases.push(l);
        self
    }
    pub fn short_alias(mut self, c: char) -> Self {
        self.hidden_short_aliases.push(c);
        self
    }
    pub fn value_name(mut self, v: &'static str) -> Self {
        self.value_name = Some(v);
        if self.value == ValueKind::None {
            self.value = ValueKind::Required;
        }
        self
    }
    pub fn takes_value(mut self, v: &'static str) -> Self {
        self.value = ValueKind::Required;
        self.value_name = Some(v);
        self
    }
    pub fn optional_value(mut self, v: &'static str) -> Self {
        self.value = ValueKind::Optional;
        self.value_name = Some(v);
        self
    }
    pub fn num_values(mut self, n: usize) -> Self {
        self.num_values = n;
        self
    }
    pub fn multiple(mut self) -> Self {
        self.multiple = true;
        self
    }
    pub fn required(mut self) -> Self {
        self.required = true;
        self
    }
    pub fn help(mut self, h: &'static str) -> Self {
        self.help = h;
        self
    }
    pub fn long_help(mut self, h: &'static str) -> Self {
        self.long_help = Some(h);
        self
    }
    pub fn heading(mut self, h: &'static str) -> Self {
        self.heading = Some(h);
        self
    }
    pub fn hide(mut self) -> Self {
        self.hide = true;
        self
    }
    pub fn conflicts(mut self, ids: &[&'static str]) -> Self {
        self.conflicts.extend_from_slice(ids);
        self
    }
    pub fn requires(mut self, ids: &[&'static str]) -> Self {
        self.requires.extend_from_slice(ids);
        self
    }
    pub fn overrides(mut self, ids: &[&'static str]) -> Self {
        self.overrides.extend_from_slice(ids);
        self
    }
    pub fn possible(mut self, vs: &[&'static str]) -> Self {
        self.possible.extend_from_slice(vs);
        self
    }
    pub fn default(mut self, v: &'static str) -> Self {
        self.default = Some(v);
        self
    }
    pub fn allow_hyphen(mut self) -> Self {
        self.allow_hyphen = true;
        self
    }
    pub fn trailing(mut self) -> Self {
        self.trailing = true;
        self
    }

    /// The left-hand column text used in `--help` output.
    pub fn spec_string(&self) -> String {
        if self.positional {
            let name = self.value_name.unwrap_or(self.id);
            let mut s = if self.required {
                format!("<{name}>")
            } else {
                format!("[{name}]")
            };
            if self.multiple {
                s.push_str("...");
            }
            return s;
        }
        let mut s = String::new();
        match (self.short, self.long) {
            (Some(c), Some(l)) => {
                s.push('-');
                s.push(c);
                s.push_str(", --");
                s.push_str(l);
            }
            (Some(c), None) => {
                s.push('-');
                s.push(c);
            }
            (None, Some(l)) => {
                s.push_str("    --");
                s.push_str(l);
            }
            (None, None) => {}
        }
        match self.value {
            ValueKind::None => {}
            ValueKind::Required => {
                let n = self.value_name.unwrap_or("value");
                if self.num_values > 1 {
                    for _ in 0..self.num_values {
                        s.push_str(&format!(" <{n}>"));
                    }
                } else {
                    s.push_str(&format!(" <{n}>"));
                }
                if self.multiple {
                    s.push_str("...");
                }
            }
            ValueKind::Optional => {
                let n = self.value_name.unwrap_or("value");
                s.push_str(&format!("[=<{n}>]"));
            }
        }
        s
    }
}

/// A subcommand entry as rendered in a `Commands:` section.
#[derive(Clone)]
pub struct Command {
    pub name: &'static str,
    pub visible_aliases: Vec<&'static str>,
    pub hidden_aliases: Vec<&'static str>,
    pub about: &'static str,
    pub long_about: Option<&'static str>,
    /// Replaces the generated usage. Lines are joined with the `Usage: `/7-space prefix.
    pub usage: Option<&'static str>,
    pub args: Vec<Arg>,
    pub subcommands: Vec<Command>,
    pub subcommand_heading: Option<&'static str>,
    pub subcommand_required: bool,
    pub hide: bool,
    /// Do not add the standard `--color`/`-h` options.
    pub no_std_opts: bool,
    /// External-style: pass remaining args through untouched (aliases).
    pub external: bool,
    pub after_help: Option<&'static str>,
}

impl Command {
    pub fn new(name: &'static str) -> Command {
        Command {
            name,
            visible_aliases: Vec::new(),
            hidden_aliases: Vec::new(),
            about: "",
            long_about: None,
            usage: None,
            args: Vec::new(),
            subcommands: Vec::new(),
            subcommand_heading: None,
            subcommand_required: false,
            hide: false,
            no_std_opts: false,
            external: false,
            after_help: None,
        }
    }
    pub fn about(mut self, a: &'static str) -> Self {
        self.about = a;
        self
    }
    pub fn long_about(mut self, a: &'static str) -> Self {
        self.long_about = Some(a);
        self
    }
    pub fn usage(mut self, u: &'static str) -> Self {
        self.usage = Some(u);
        self
    }
    pub fn arg(mut self, a: Arg) -> Self {
        self.args.push(a);
        self
    }
    pub fn args(mut self, a: Vec<Arg>) -> Self {
        self.args.extend(a);
        self
    }
    pub fn subcommand(mut self, c: Command) -> Self {
        self.subcommands.push(c);
        self
    }
    pub fn visible_alias(mut self, a: &'static str) -> Self {
        self.visible_aliases.push(a);
        self
    }
    pub fn hidden_alias(mut self, a: &'static str) -> Self {
        self.hidden_aliases.push(a);
        self
    }
    pub fn subcommand_heading(mut self, h: &'static str) -> Self {
        self.subcommand_heading = Some(h);
        self
    }
    pub fn subcommand_required(mut self) -> Self {
        self.subcommand_required = true;
        self
    }

    pub fn display_name(&self) -> String {
        let mut s = self.name.to_string();
        for a in &self.visible_aliases {
            s.push_str(", ");
            s.push_str(a);
        }
        s
    }

    pub fn matches_name(&self, s: &str) -> bool {
        self.name == s
            || self.visible_aliases.iter().any(|a| *a == s)
            || self.hidden_aliases.iter().any(|a| *a == s)
    }

    pub fn find_arg(&self, id: &str) -> Option<&Arg> {
        self.args.iter().find(|a| a.id == id)
    }
}

