//! Reproduction of clap v4's help formatting.

use super::spec::{Arg, Command, ValueKind};

pub const MAX_TERM_WIDTH: usize = 88;
const INDENT: usize = 2;
const TAB: usize = 4;

pub fn term_width() -> usize {
    let detected = std::env::var("COLUMNS")
        .ok()
        .and_then(|s| s.trim().parse::<usize>().ok())
        .filter(|n| *n > 0)
        .unwrap_or(100);
    detected.min(MAX_TERM_WIDTH)
}

fn display_width(s: &str) -> usize {
    s.chars().count()
}

/// Greedy word wrap that honours pre-existing newlines as hard breaks.
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let mut out = Vec::new();
    for raw_line in text.split('\n') {
        let line = raw_line.trim_end();
        if line.is_empty() {
            out.push(String::new());
            continue;
        }
        // Preserve leading whitespace of the source line.
        let lead: String = line.chars().take_while(|c| *c == ' ').collect();
        let body = &line[lead.len()..];
        let mut cur = String::new();
        let mut cur_w = 0usize;
        let mut first = true;
        for word in body.split(' ').filter(|w| !w.is_empty()) {
            let w = display_width(word);
            if first {
                cur.push_str(&lead);
                cur.push_str(word);
                cur_w = display_width(&lead) + w;
                first = false;
            } else if cur_w + 1 + w <= width {
                cur.push(' ');
                cur.push_str(word);
                cur_w += 1 + w;
            } else {
                out.push(std::mem::take(&mut cur));
                cur.push_str(word);
                cur_w = w;
            }
        }
        if !cur.is_empty() || first {
            out.push(cur);
        }
    }
    out
}

fn push_wrapped(out: &mut String, text: &str, indent: usize, width: usize) {
    let pad = " ".repeat(indent);
    let avail = width.saturating_sub(indent);
    for line in wrap(text, avail) {
        if line.is_empty() {
            // clap emits the indentation even for blank continuation lines
            out.push_str(&pad);
            out.push('\n');
        } else {
            out.push_str(&pad);
            out.push_str(&line);
            out.push('\n');
        }
    }
}

/// Visible args, split into positionals and options, in declaration order.
fn visible_args<'a>(cmd: &'a Command, use_long: bool) -> (Vec<&'a Arg>, Vec<&'a Arg>, Vec<(&'static str, Vec<&'a Arg>)>) {
    let mut pos = Vec::new();
    let mut opts = Vec::new();
    let mut headings: Vec<(&'static str, Vec<&Arg>)> = Vec::new();
    let _ = use_long;
    for a in &cmd.args {
        if a.hide {
            continue;
        }
        if a.positional {
            pos.push(a);
        } else if let Some(h) = a.heading {
            if let Some(e) = headings.iter_mut().find(|(n, _)| *n == h) {
                e.1.push(a);
            } else {
                headings.push((h, vec![a]));
            }
        } else {
            opts.push(a);
        }
    }
    (pos, opts, headings)
}

fn longest_spec(args: &[&Arg]) -> usize {
    args.iter().map(|a| display_width(&a.spec_string())).max().unwrap_or(0)
}

fn spec_vals(arg: &Arg) -> String {
    let mut extra: Vec<String> = Vec::new();
    if !arg.possible.is_empty() {
        extra.push(format!("[possible values: {}]", arg.possible.join(", ")));
    }
    if extra.is_empty() {
        String::new()
    } else {
        format!(" {}", extra.join(" "))
    }
}

fn will_args_wrap(args: &[&Arg], longest: usize, term_w: usize, use_long: bool) -> bool {
    args.iter().any(|a| {
        let h = if use_long { a.long_help.unwrap_or(a.help) } else { a.help };
        let sv = spec_vals(a);
        let h_w = display_width(h) + display_width(&sv);
        let taken = longest + TAB * 2;
        term_w >= taken && (taken as f64 / term_w as f64) > 0.40 && h_w > term_w - taken
    })
}

fn write_args(out: &mut String, args: &[&Arg], term_w: usize, use_long: bool) {
    let longest = longest_spec(args);
    let next_line = use_long || will_args_wrap(args, longest, term_w, use_long);
    let mut first = true;
    for a in args {
        if next_line && use_long && !first {
            out.push('\n');
        }
        first = false;
        let spec = a.spec_string();
        let help_text = {
            let base = if use_long { a.long_help.unwrap_or(a.help) } else { a.help };
            let sv = spec_vals(a);
            if sv.is_empty() {
                base.to_string()
            } else if base.contains('\n') {
                format!("{base}\n\n{}", sv.trim_start())
            } else {
                format!("{base}{sv}")
            }
        };
        if next_line {
            out.push_str(&" ".repeat(INDENT));
            out.push_str(&spec);
            out.push('\n');
            if !help_text.is_empty() {
                push_wrapped(out, &help_text, INDENT + TAB * 2, term_w);
            }
        } else {
            let col = INDENT + longest + 2;
            let pad = col.saturating_sub(INDENT + display_width(&spec));
            if help_text.is_empty() {
                out.push_str(&" ".repeat(INDENT));
                out.push_str(&spec);
                out.push('\n');
            } else {
                let avail = term_w.saturating_sub(col).max(10);
                let lines = wrap(&help_text, avail);
                for (i, line) in lines.iter().enumerate() {
                    if i == 0 {
                        out.push_str(&" ".repeat(INDENT));
                        out.push_str(&spec);
                        out.push_str(&" ".repeat(pad));
                    } else {
                        out.push_str(&" ".repeat(col));
                    }
                    out.push_str(line);
                    out.push('\n');
                }
            }
        }
    }
}

fn write_subcommands(out: &mut String, subs: &[&Command], term_w: usize) {
    let longest = subs.iter().map(|c| display_width(&c.display_name())).max().unwrap_or(0);
    let col = INDENT + longest + 2;
    for c in subs {
        let name = c.display_name();
        let pad = col.saturating_sub(INDENT + display_width(&name));
        let avail = term_w.saturating_sub(col).max(10);
        let lines = wrap(c.about, avail);
        if lines.is_empty() {
            out.push_str(&" ".repeat(INDENT));
            out.push_str(&name);
            out.push('\n');
            continue;
        }
        for (i, line) in lines.iter().enumerate() {
            if i == 0 {
                out.push_str(&" ".repeat(INDENT));
                out.push_str(&name);
                out.push_str(&" ".repeat(pad));
            } else {
                out.push_str(&" ".repeat(col));
            }
            out.push_str(line);
            out.push('\n');
        }
    }
}

pub fn generated_usage(cmd: &Command, path: &str) -> String {
    let mut s = String::from(path);
    let (pos, opts, headings) = visible_args(cmd, false);
    let has_opts = !opts.is_empty() || !headings.is_empty();
    if has_opts {
        s.push_str(" [OPTIONS]");
    }
    for p in &pos {
        s.push(' ');
        s.push_str(&p.spec_string());
    }
    if !cmd.subcommands.is_empty() {
        s.push_str(" <COMMAND>");
    }
    s
}

pub fn render_usage_block(cmd: &Command, path: &str) -> String {
    let mut out = String::new();
    match cmd.usage {
        Some(u) => {
            for (i, line) in u.lines().enumerate() {
                if i == 0 {
                    out.push_str("Usage: ");
                } else {
                    out.push_str("       ");
                }
                out.push_str(line);
                out.push('\n');
            }
        }
        None => {
            out.push_str("Usage: ");
            out.push_str(&generated_usage(cmd, path));
            out.push('\n');
        }
    }
    out
}

pub fn render_help(cmd: &Command, path: &str, use_long: bool) -> String {
    let term_w = term_width();
    let mut out = String::new();

    let about = if use_long {
        cmd.long_about.unwrap_or(cmd.about)
    } else {
        cmd.about
    };
    if !about.is_empty() {
        for line in wrap(about, term_w) {
            out.push_str(&line);
            out.push('\n');
        }
        out.push('\n');
    }

    out.push_str(&render_usage_block(cmd, path));

    // Commands sections
    let visible_subs: Vec<&Command> = cmd.subcommands.iter().filter(|c| !c.hide).collect();
    if !visible_subs.is_empty() {
        let mut groups: Vec<(&str, Vec<&Command>)> = Vec::new();
        for c in &visible_subs {
            let h = c.subcommand_heading.unwrap_or(cmd.subcommand_heading.unwrap_or("Commands"));
            if let Some(e) = groups.iter_mut().find(|(n, _)| *n == h) {
                e.1.push(c);
            } else {
                groups.push((h, vec![c]));
            }
        }
        for (h, subs) in groups {
            out.push('\n');
            out.push_str(h);
            out.push_str(":\n");
            write_subcommands(&mut out, &subs, term_w);
        }
    }

    let (pos, opts, headings) = visible_args(cmd, use_long);
    if !pos.is_empty() {
        out.push_str("\nArguments:\n");
        write_args(&mut out, &pos, term_w, use_long);
    }
    if !opts.is_empty() {
        out.push_str("\nOptions:\n");
        write_args(&mut out, &opts, term_w, use_long);
    }
    for (h, args) in headings {
        out.push('\n');
        out.push_str(h);
        out.push_str(":\n");
        write_args(&mut out, &args, term_w, use_long);
    }

    if let Some(after) = cmd.after_help {
        out.push('\n');
        push_wrapped(&mut out, after, 0, term_w);
    }
    out
}

