//! Argument parser reproducing clap v4 semantics for the subset StGit needs.

use std::collections::HashMap;

use super::help;
use super::spec::{Arg, Command, ValueKind};

#[derive(Default, Debug)]
pub struct Matches {
    /// (id, value) pairs in command-line order.
    pub occurrences: Vec<(String, Option<String>)>,
    map: HashMap<String, Vec<String>>,
    counts: HashMap<String, usize>,
    pub subcommand: Option<(String, Box<Matches>)>,
    pub external: Vec<String>,
}

impl Matches {
    fn add(&mut self, id: &str, val: Option<String>) {
        *self.counts.entry(id.to_string()).or_insert(0) += 1;
        if let Some(v) = val.clone() {
            self.map.entry(id.to_string()).or_default().push(v);
        } else {
            self.map.entry(id.to_string()).or_default();
        }
        self.occurrences.push((id.to_string(), val));
    }
    fn remove(&mut self, id: &str) {
        self.counts.remove(id);
        self.map.remove(id);
        self.occurrences.retain(|(i, _)| i != id);
    }
    pub fn is_present(&self, id: &str) -> bool {
        self.counts.contains_key(id)
    }
    pub fn count(&self, id: &str) -> usize {
        *self.counts.get(id).unwrap_or(&0)
    }
    pub fn value_of(&self, id: &str) -> Option<&str> {
        self.map.get(id).and_then(|v| v.first()).map(|s| s.as_str())
    }
    pub fn values_of(&self, id: &str) -> Vec<&str> {
        self.map.get(id).map(|v| v.iter().map(|s| s.as_str()).collect()).unwrap_or_default()
    }
    pub fn subcommand_name(&self) -> Option<&str> {
        self.subcommand.as_ref().map(|(n, _)| n.as_str())
    }
}

#[derive(Debug)]
pub enum CliError {
    DisplayHelp(String),
    DisplayVersion,
    /// Rendered error message body (without the trailing usage/hint).
    Error {
        message: String,
        usage: Option<String>,
        hint: bool,
    },
}

impl CliError {
    pub fn render(&self) -> String {
        match self {
            CliError::DisplayHelp(s) => s.clone(),
            CliError::DisplayVersion => String::new(),
            CliError::Error { message, usage, hint } => {
                let mut s = format!("error: {message}\n");
                if let Some(u) = usage {
                    s.push('\n');
                    s.push_str(u);
                }
                if *hint {
                    s.push_str("\nFor more information, try '--help'.\n");
                }
                s
            }
        }
    }
}

fn usage_block(cmd: &Command, path: &str) -> String {
    help::render_usage_block(cmd, path)
}

fn err(cmd: &Command, path: &str, message: String) -> CliError {
    CliError::Error { message, usage: Some(usage_block(cmd, path)), hint: true }
}

fn err_nousage(message: String) -> CliError {
    CliError::Error { message, usage: None, hint: true }
}

/// Levenshtein distance for "did you mean" suggestions.
fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn best_match<'a>(input: &str, candidates: impl Iterator<Item = &'a str>) -> Option<&'a str> {
    let mut best: Option<(usize, &str)> = None;
    for c in candidates {
        let d = edit_distance(input, c);
        let threshold = (input.chars().count() + 2) / 3;
        if d <= threshold.max(1) {
            if best.map(|(bd, _)| d < bd).unwrap_or(true) {
                best = Some((d, c));
            }
        }
    }
    best.map(|(_, c)| c)
}

fn arg_display(a: &Arg) -> String {
    if a.positional {
        let n = a.value_name.unwrap_or(a.id);
        let mut s = if a.required { format!("<{n}>") } else { format!("[{n}]") };
        if a.multiple {
            s.push_str("...");
        }
        return s;
    }
    let mut s = String::new();
    if let Some(l) = a.long {
        s.push_str("--");
        s.push_str(l);
    } else if let Some(c) = a.short {
        s.push('-');
        s.push(c);
    }
    match a.value {
        ValueKind::None => {}
        ValueKind::Required => {
            let n = a.value_name.unwrap_or("value");
            s.push_str(&format!(" <{n}>"));
            if a.multiple {
                s.push_str("...");
            }
        }
        ValueKind::Optional => {
            let n = a.value_name.unwrap_or("value");
            s.push_str(&format!("[=<{n}>]"));
        }
    }
    s
}

struct Ctx<'a> {
    cmd: &'a Command,
    path: String,
}

pub fn parse(cmd: &Command, path: &str, argv: &[String]) -> Result<Matches, CliError> {
    let ctx = Ctx { cmd, path: path.to_string() };
    let mut m = Matches::default();
    let mut i = 0usize;
    let mut no_more_opts = false;
    let mut positional_idx = 0usize;
    let positionals: Vec<&Arg> = cmd.args.iter().filter(|a| a.positional).collect();
    let mut trailing_mode = false;

    while i < argv.len() {
        let a = &argv[i];
        if trailing_mode {
            let p = positionals[positional_idx.min(positionals.len().saturating_sub(1))];
            m.add(p.id, Some(a.clone()));
            i += 1;
            continue;
        }
        if !no_more_opts && a == "--" {
            no_more_opts = true;
            i += 1;
            continue;
        }
        if !no_more_opts && a.starts_with("--") && a.len() > 2 {
            let body = &a[2..];
            let (name, inline) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            if name == "help" && !cmd.no_std_opts {
                return Err(CliError::DisplayHelp(help::render_help(cmd, &ctx.path, true)));
            }
            let found = cmd.args.iter().find(|x| {
                x.long == Some(name) || x.hidden_long_aliases.iter().any(|al| *al == name)
            });
            let Some(arg) = found else {
                let mut msg = format!("unexpected argument '--{name}' found");
                let cands: Vec<&str> = cmd.args.iter().filter_map(|x| x.long).collect();
                if let Some(s) = best_match(name, cands.into_iter()) {
                    msg.push_str(&format!("\n\n  tip: a similar argument exists: '--{s}'"));
                }
                return Err(err(cmd, &ctx.path, msg));
            };
            match arg.value {
                ValueKind::None => {
                    if inline.is_some() {
                        return Err(err(
                            cmd,
                            &ctx.path,
                            format!(
                                "unexpected value '{}' for '--{name}' found; no more were expected",
                                inline.unwrap()
                            ),
                        ));
                    }
                    apply(&mut m, arg, None, cmd, &ctx.path)?;
                }
                ValueKind::Optional => {
                    apply(&mut m, arg, inline, cmd, &ctx.path)?;
                }
                ValueKind::Required => {
                    if let Some(v) = inline {
                        apply(&mut m, arg, Some(v), cmd, &ctx.path)?;
                    } else {
                        let mut vals = Vec::new();
                        for _ in 0..arg.num_values.max(1) {
                            i += 1;
                            if i >= argv.len() {
                                return Err(missing_value(cmd, &ctx.path, arg));
                            }
                            vals.push(argv[i].clone());
                        }
                        for v in vals {
                            apply(&mut m, arg, Some(v), cmd, &ctx.path)?;
                        }
                    }
                }
            }
            i += 1;
            continue;
        }
        if !no_more_opts && a.starts_with('-') && a.len() > 1 && a != "-" {
            // Short flag cluster
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0usize;
            let mut consumed_next = false;
            while ci < chars.len() {
                let c = chars[ci];
                if c == 'h' && !cmd.no_std_opts && !cmd.args.iter().any(|x| x.short == Some('h')) {
                    return Err(CliError::DisplayHelp(help::render_help(cmd, &ctx.path, false)));
                }
                let found = cmd
                    .args
                    .iter()
                    .find(|x| x.short == Some(c) || x.hidden_short_aliases.contains(&c));
                let Some(arg) = found else {
                    // Could be a negative number for allow_hyphen positional
                    let rest: String = chars[ci..].iter().collect();
                    let _ = rest;
                    return Err(err(cmd, &ctx.path, format!("unexpected argument '-{c}' found")));
                };
                match arg.value {
                    ValueKind::None => {
                        apply(&mut m, arg, None, cmd, &ctx.path)?;
                        ci += 1;
                    }
                    ValueKind::Optional => {
                        let rest: String = chars[ci + 1..].iter().collect();
                        let v = if rest.is_empty() {
                            None
                        } else if let Some(stripped) = rest.strip_prefix('=') {
                            Some(stripped.to_string())
                        } else {
                            Some(rest)
                        };
                        apply(&mut m, arg, v, cmd, &ctx.path)?;
                        ci = chars.len();
                    }
                    ValueKind::Required => {
                        let rest: String = chars[ci + 1..].iter().collect();
                        if !rest.is_empty() {
                            let v = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                            apply(&mut m, arg, Some(v), cmd, &ctx.path)?;
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return Err(missing_value(cmd, &ctx.path, arg));
                            }
                            let v = argv[i].clone();
                            apply(&mut m, arg, Some(v), cmd, &ctx.path)?;
                            consumed_next = true;
                        }
                        ci = chars.len();
                    }
                }
            }
            let _ = consumed_next;
            i += 1;
            continue;
        }

        // Positional or subcommand
        if !cmd.subcommands.is_empty() && m.subcommand.is_none() {
            if let Some(sub) = cmd.subcommands.iter().find(|s| s.matches_name(a)) {
                let sub_path = format!("{} {}", ctx.path, sub.name);
                let rest: Vec<String> = argv[i + 1..].to_vec();
                if sub.external {
                    let mut sm = Matches::default();
                    sm.external = rest;
                    m.subcommand = Some((sub.name.to_string(), Box::new(sm)));
                    return finish(m, cmd, &ctx.path);
                }
                let sm = parse(sub, &sub_path, &rest)?;
                m.subcommand = Some((sub.name.to_string(), Box::new(sm)));
                return finish(m, cmd, &ctx.path);
            }
        }
        if positional_idx >= positionals.len() {
            if !cmd.subcommands.is_empty() {
                let mut msg = format!("unrecognized subcommand '{a}'");
                let cands: Vec<&str> = cmd.subcommands.iter().filter(|c| !c.hide).map(|c| c.name).collect();
                if let Some(s) = best_match(a, cands.into_iter()) {
                    msg.push_str(&format!("\n\n  tip: a similar subcommand exists: '{s}'"));
                }
                return Err(err(cmd, &ctx.path, msg));
            }
            return Err(err(
                cmd,
                &ctx.path,
                format!("unexpected argument '{a}' found"),
            ));
        }
        let p = positionals[positional_idx];
        apply(&mut m, p, Some(a.clone()), cmd, &ctx.path)?;
        if p.trailing {
            trailing_mode = true;
        }
        if !p.multiple {
            positional_idx += 1;
        }
        i += 1;
    }
    finish(m, cmd, &ctx.path)
}

fn missing_value(cmd: &Command, path: &str, arg: &Arg) -> CliError {
    let mut e = err(
        cmd,
        path,
        format!("a value is required for '{}' but none was supplied", arg_display(arg)),
    );
    if let CliError::Error { usage, .. } = &mut e {
        *usage = None;
    }
    e
}

fn apply(
    m: &mut Matches,
    arg: &Arg,
    val: Option<String>,
    cmd: &Command,
    path: &str,
) -> Result<(), CliError> {
    if let (Some(v), false) = (val.as_ref(), arg.possible.is_empty()) {
        if !arg.possible.iter().any(|p| p == v) {
            let msg = format!(
                "invalid value '{v}' for '{}'\n  [possible values: {}]",
                arg_display(arg),
                arg.possible.join(", ")
            );
            return Err(err_nousage(msg));
        }
    }
    for o in &arg.overrides {
        m.remove(o);
    }
    for c in &arg.conflicts {
        if m.is_present(c) {
            let other = cmd.find_arg(c).map(arg_display).unwrap_or_else(|| c.to_string());
            return Err(err(
                cmd,
                path,
                format!(
                    "the argument '{}' cannot be used with '{}'",
                    other,
                    arg_display(arg)
                ),
            ));
        }
    }
    // Reverse conflicts
    for other in &cmd.args {
        if other.conflicts.iter().any(|c| *c == arg.id) && m.is_present(other.id) {
            return Err(err(
                cmd,
                path,
                format!(
                    "the argument '{}' cannot be used with '{}'",
                    arg_display(other),
                    arg_display(arg)
                ),
            ));
        }
    }
    if !arg.multiple && arg.value != ValueKind::None && m.is_present(arg.id) {
        // clap allows repeats and keeps the last unless multiple; emulate "last wins"
        m.remove(arg.id);
    }
    m.add(arg.id, val);
    Ok(())
}

fn finish(mut m: Matches, cmd: &Command, path: &str) -> Result<Matches, CliError> {
    if cmd.subcommand_required && m.subcommand.is_none() {
        let mut s = format!(
            "error: '{path}' requires a subcommand but one was not provided\n"
        );
        s.push_str("  [subcommands: ");
        let names: Vec<&str> = cmd.subcommands.iter().filter(|c| !c.hide).map(|c| c.name).collect();
        s.push_str(&names.join(", "));
        s.push_str("]\n");
        return Err(CliError::Error {
            message: s
                .trim_start_matches("error: ")
                .trim_end_matches('\n')
                .to_string(),
            usage: Some(usage_block(cmd, path)),
            hint: true,
        });
    }
    for a in &cmd.args {
        if a.required && !m.is_present(a.id) {
            return Err(err(
                cmd,
                path,
                format!(
                    "the following required arguments were not provided:\n  {}",
                    arg_display(a)
                ),
            ));
        }
        if let Some(d) = a.default {
            if !m.is_present(a.id) {
                m.map.insert(a.id.to_string(), vec![d.to_string()]);
            }
        }
    }
    Ok(m)
}

