pub mod help;
pub mod parse;
pub mod spec;

pub use parse::{CliError, Matches};
pub use spec::{Arg, Command, ValueKind};

pub const COLOR_SHORT: &str = "When to colorize output: auto, always, ansi, never";
pub const COLOR_LONG: &str = "Specify when to colorize the output.

`auto` (the default) enables colored output only when outputting to a terminal
or TTY. The `NO_COLOR` environment variable is respected.

`always` and `never` unconditionlly enable/disable colored output,
respectively.

`ansi` forces color to be output using ANSI escape sequences, even in a
Windows console.";

pub fn color_arg() -> Arg {
    Arg::new("color")
        .long("color")
        .takes_value("when")
        .possible(&["auto", "always", "ansi", "never"])
        .help(COLOR_SHORT)
        .long_help(COLOR_LONG)
}

pub fn help_arg() -> Arg {
    Arg::new("help").short('h').long("help").help("Print help (see more with '--help')")
}

/// Append the trailing standard options (`--color`, `-h/--help`) that every
/// StGit command carries.
pub fn with_std_opts(mut cmd: Command) -> Command {
    if cmd.no_std_opts {
        return cmd;
    }
    if !cmd.args.iter().any(|a| a.id == "color") {
        cmd.args.push(color_arg());
    }
    cmd.args.push(help_arg());
    for sub in cmd.subcommands.iter_mut() {
        let taken = std::mem::replace(sub, Command::new(""));
        *sub = with_std_opts(taken);
    }
    cmd
}

pub fn branch_arg() -> Arg {
    Arg::new("branch")
        .short('b')
        .long("branch")
        .takes_value("branch")
        .help("Use <branch> instead of current branch")
}

